package dev.bennett.codexmeter;
import org.json.*;import java.time.*;import java.util.*;import java.nio.file.*;
public final class Beta996SelfTest {
 static int checks;static final String ACCOUNT="a".repeat(64);static void check(boolean v,String s){checks++;if(!v)throw new AssertionError(s);}interface Call{void run()throws Exception;}static void reject(Call c,String s){boolean failed=false;try{c.run();}catch(Exception expected){failed=true;}check(failed,s);}static void equal(JSONObject a,JSONObject b,String key){check(a.get(key).toString().equals(b.get(key).toString()),"Immutable "+key);}
 public static void main(String[] args)throws Exception{
  long now=LocalDate.of(2028,3,1).atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli();JSONObject old=new JSONObject(Files.readString(Path.of(args[0]))),oldYear=new JSONObject(Files.readString(Path.of(args[1])));JSONObject upgraded=BetaV4.upgrade(old,now);
  check(upgraded.getInt("rules")==4&&upgraded.getInt("catalog_revision")==2,"Rules4, only catalog2");for(String k:new String[]{"cutover","total","level","progress","next_cost","days","rewards","equipped","enabled"})equal(old,upgraded,k);
  for(String kind:new String[]{"honors","titles"}){JSONObject previous=old.getJSONObject(kind),fresh=upgraded.getJSONObject(kind);Iterator<String> ids=previous.keys();while(ids.hasNext()){String id=ids.next();check(previous.getLong(id)==fresh.getLong(id),"Original earned time "+id);}}
  check(upgraded.getJSONObject("honors").has("rpg4.days_14")&&upgraded.getJSONObject("titles").has("rpg4.title_level_20"),"Existing proof retroactively grants eligible additions");JSONObject again=BetaV4.upgrade(upgraded,now);check(again.toString().equals(upgraded.toString()),"Repeat catalog upgrade idempotent");
  JSONObject restored=BetaV4.restore(upgraded,old,ACCOUNT,now);for(String k:new String[]{"cutover","total","level","progress","days","rewards","equipped"})equal(upgraded,restored,k);check(restored.getJSONObject("titles").has("rpg4.title_level_20"),"Old backup cannot erase new titles");
  JSONObject imported=BetaV4.restore(null,old,ACCOUNT,now);check(imported.getInt("catalog_revision")==2&&imported.getLong("total")==old.getLong("total"),"9.9.5 backup accepted on clean same account");JSONObject roundtrip=BetaV4.restore(upgraded,upgraded,ACCOUNT,now);equal(upgraded,roundtrip,"total");
  JSONObject forged=new JSONObject(old.toString());forged.getJSONObject("titles").put("rpg4.title_level_100",now-1);reject(()->BetaV4.restore(upgraded,forged,ACCOUNT,now),"No modern claims in old revision");JSONObject future=new JSONObject(upgraded.toString()).put("catalog_revision",99);reject(()->BetaV4.restore(upgraded,future,ACCOUNT,now),"Newer catalog protected");reject(()->BetaV4.upgrade(future,now),"Unknown future persisted state never downgraded");JSONObject fractional=new JSONObject(upgraded.toString()).put("catalog_revision",2.5);reject(()->BetaV4.restore(upgraded,fractional,ACCOUNT,now),"Fractional revision refused");JSONObject bad=new JSONObject(upgraded.toString()).put("total",upgraded.getLong("total")+1);reject(()->BetaV4.restore(upgraded,bad,ACCOUNT,now),"No forged XP");JSONObject secret=new JSONObject(upgraded.toString()).put("access_token","SYNTHETIC");reject(()->BetaV4.restore(upgraded,secret,ACCOUNT,now),"No authentication in backup");reject(()->BetaV4.restore(upgraded,upgraded,"b".repeat(64),now),"Wrong account");
  JSONObject year=BetaV4.upgrade(oldYear,now);for(String k:new String[]{"total","level","progress","days","rewards","equipped"})equal(oldYear,year,k);check(year.getJSONObject("honors").has("rpg4.days_365"),"Long-term evidence awards additions without extra XP");
  HashSet<String> ids=new HashSet<>();for(String[] e:BetaCatalog.ALL){check(ids.add(e[0]),"Stable unique ID");check(!e[1].isBlank()&&!e[2].isBlank()&&!e[3].isBlank()&&!e[4].isBlank(),"Bilingual name/condition");check(Set.of("common","rare","epic","legendary","mythic").contains(e[6]),"Known rarity");if(BetaCatalog.title(e[0])){check(BetaCatalog.name(e[0],"민수",true).contains("민수"),"Korean named title");check(BetaCatalog.name(e[0],"Alex Smith",false).contains("Alex Smith"),"English named title");}else check(!e[1].contains("%s"),"No user name in achievement ID/name");if(e.length>7){int[] p=BetaCatalog.progress(upgraded,e[0],now);check(p[1]>0&&p[0]>=0,"Correct progress "+e[0]);if(upgraded.getJSONObject(BetaCatalog.title(e[0])?"titles":"honors").has(e[0]))check(upgraded.getJSONObject("days").length()>0,"Evidence required");}}
  check(BetaCatalog.count(false)==37&&BetaCatalog.count(true)==24,"37 honors/24 titles");check(old.getJSONObject("honors").length()<upgraded.getJSONObject("honors").length(),"Added near-term goals");
  LocalDate start=LocalDate.of(2027,1,1);JSONObject small=BetaV4.create(ACCOUNT,start.atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli());for(int i=0;i<5;i++){long at=start.plusDays(i).atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli()+3600000;BetaV4.confirm(small,ACCOUNT,at,at,true);if(i==2){check(small.getJSONObject("honors").has("rpg4.days_3"),"Three-day award");check(!small.getJSONObject("honors").has("rpg4.full_weeks_1"),"Distinct calendar week condition");}}
  check(small.getLong("total")==25,"Calendar Jan1Friday→5days: day5 +one3dayweek20");
  int earliest=99,latest=0;for(int y:new int[]{2027,2028})for(int d=1;d<=Year.of(y).length();d++){LocalDate first=LocalDate.ofYearDay(y,d);long cut=first.atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli();JSONObject s=BetaV4.create(ACCOUNT,cut);int reached=0;for(int i=0;i<30;i++){LocalDate date=first.plusDays(i);long at=date.atStartOfDay(BetaV4.ZONE).toInstant().toEpochMilli()+3600000;if(date.getDayOfWeek().getValue()<=5)BetaV4.confirm(s,ACCOUNT,at,at,true);if(reached==0&&s.getInt("level")>=30)reached=i+1;}check(reached>0,"Five days/week Lv30 before30 "+first);earliest=Math.min(earliest,reached);latest=Math.max(latest,reached);}
  long begin=System.nanoTime();for(int i=0;i<10000;i++)BetaV4.summary(upgraded,now);System.out.println("10000 V4 summaries: "+(System.nanoTime()-begin)/1000000+"ms; no network/DB");System.out.println("Every2027/2028 start five days/week Lv30="+earliest+".."+latest+" days");System.out.println("Beta9.9.6 catalog/preservation: "+checks+" checks passed; synthetic only");
 }
}
